const parseReadTimeMinutes = (str: string | undefined): number => {
  if (!str) return 5;
  const persianDigits = ['۰', '۱', '۲', '۳', '۴', '۵', '۶', '۷', '۸', '۹'];
  const arabicDigits = ['٠', '١', '٢', '٣', '٤', '٥', '٦', '٧', '٨', '٩'];
  let normalized = str;
  persianDigits.forEach((p, i) => {
    normalized = normalized.replaceAll(p, String(i));
  });
  arabicDigits.forEach((a, i) => {
    normalized = normalized.replaceAll(a, String(i));
  });
  const match = normalized.match(/\d+/);
  return match ? parseInt(match[0], 10) : 5;
};

const toPersianNumber = (n: number): string => {
  const persianDigits = ['۰', '۱', '۲', '۳', '۴', '۵', '۶', '۷', '۸', '۹'];
  return String(n).replace(/\d/g, (d) => persianDigits[parseInt(d, 10)]);
};

type ActiveTab =
  | 'appointments'
  | 'home'
  | 'our-services'
  | 'works'
  | 'articles'
  | 'about'
  | 'contact'
  | 'comments'
  | 'media';
type CommentFilter = 'all' | 'pending' | 'unanswered' | 'completed' | 'rejected';

/** Check if a URL points to a video file */
const isVideoUrl = (url?: string | null): boolean => {
  if (!url) return false;
  const ext = url.split('?')[0].split('#')[0].split('.').pop()?.toLowerCase();
  return ['mp4', 'webm', 'ogg', 'mov', 'avi', 'mkv'].includes(ext || '');
};

const getInitialAdminTab = (): ActiveTab => {
  if (typeof window === 'undefined') return 'appointments';
  const urlParams = new URLSearchParams(window.location.search);
  const tabFromUrl = urlParams.get('tab');
  const validTabs: string[] = [
    'appointments',
    'home',
    'our-services',
    'works',
    'articles',
    'about',
    'contact',
    'comments',
    'media',
  ];

  if (tabFromUrl === 'pages') return 'contact';
  if (tabFromUrl === 'services') return 'about';
  if (tabFromUrl === 'gallery') return 'works';

  if (tabFromUrl && validTabs.includes(tabFromUrl)) {
    return tabFromUrl as ActiveTab;
  }
  const tabFromStorage = localStorage.getItem('parmis_admin_active_tab');
  if (tabFromStorage === 'pages') return 'contact';
  if (tabFromStorage === 'services') return 'about';
  if (tabFromStorage === 'gallery') return 'works';

  if (tabFromStorage && validTabs.includes(tabFromStorage)) {
    return tabFromStorage as ActiveTab;
  }
  return 'appointments';
};

const getInitialAdminCommentFilter = (): CommentFilter => {
  if (typeof window === 'undefined') return 'pending';
  const urlParams = new URLSearchParams(window.location.search);
  const filterFromUrl = urlParams.get('filter') as CommentFilter | null;
  const validFilters: CommentFilter[] = ['all', 'pending', 'unanswered', 'completed', 'rejected'];
  if (filterFromUrl && validFilters.includes(filterFromUrl)) {
    return filterFromUrl;
  }
  const filterFromStorage = localStorage.getItem('parmis_admin_comment_filter') as CommentFilter | null;
  if (filterFromStorage && validFilters.includes(filterFromStorage)) {
    return filterFromStorage;
  }
  return 'pending';
};

