  // ==========================================
  // BLOG CATEGORIES ACTIONS
  // ==========================================
  const handleSaveCategory = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingCategory || !editingCategory.label.trim()) return;

    setIsSavingCategory(true);
    try {
      const isEdit = Boolean(editingCategory.id && cmsData.blogCategories?.some((c: any) => c.id === editingCategory.id));
      const url = isEdit ? `/api/categories/${editingCategory.id}` : '/api/categories';
      const method = isEdit ? 'PUT' : 'POST';

      const res = await fetch(url, {
        method,
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify(editingCategory),
      });

      const data = await res.json();
      if (!res.ok) throw new Error(data.error || 'خطا در ذخیره دسته‌بندی');

      addToast('success', isEdit ? 'دسته‌بندی با موفقیت ویرایش شد.' : 'دسته‌بندی جدید با موفقیت افزوده شد.');
      notifyCmsUpdated();
      setIsCategoryModalOpen(false);
      setEditingCategory(null);
      await fetchCmsData();
    } catch (err: any) {
      addToast('error', err.message);
    } finally {
      setIsSavingCategory(false);
    }
  };

  const handleDeleteCategory = async (cat: any) => {
    if (cat.id === 'all') {
      addToast('error', 'دسته‌بندی پیش‌فرض قابل حذف نیست.');
      return;
    }

    const articlesWithCat = (cmsData?.articles || []).filter(
      (a: any) => a.category === cat.label || a.categorySlug === cat.id
    ).length;

    const msg = articlesWithCat > 0
      ? `آیا از حذف دسته‌بندی «${cat.label}» اطمینان دارید؟ (${articlesWithCat} مقاله این دسته به دسته‌بندی عمومی منتقل خواهند شد)`
      : `آیا از حذف دسته‌بندی «${cat.label}» اطمینان دارید؟`;

    if (!window.confirm(msg)) return;

    try {
      const res = await fetch(`/api/categories/${cat.id}`, {
        method: 'DELETE',
        headers: { Authorization: `Bearer ${token}` },
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || 'خطا در حذف دسته‌بندی');

      addToast('success', 'دسته‌بندی با موفقیت حذف شد.');
      notifyCmsUpdated();
      await fetchCmsData();
    } catch (err: any) {
      addToast('error', err.message);
    }
  };

