  const updateHomeSection = <K extends keyof HomeSettingsType>(
    section: K,
    updater: (prev: HomeSettingsType[K]) => HomeSettingsType[K]
  ) => {
    setCmsData((prev: any) => {
      const currentHome: HomeSettingsType = prev?.homeSettings || defaultHomeSettings;
      const currentSec = currentHome[section] || defaultHomeSettings[section];
      const updatedSec = updater(currentSec);
      return {
        ...prev,
        homeSettings: {
          ...currentHome,
          [section]: updatedSec,
        },
      };
    });
  };

  const handleSaveHomeSection = async (sectionTitle: string) => {
    setIsSavingHomeSettings(true);
    try {
      const settings = cmsData.homeSettings || defaultHomeSettings;

      // Keep siteImages.heroMainImage synchronized if hero.imageUrl exists
      if (settings?.hero?.imageUrl && cmsData.siteImages?.heroMainImage) {
        const updatedSiteImages = {
          ...cmsData.siteImages,
          heroMainImage: {
            ...cmsData.siteImages.heroMainImage,
            url: settings.hero.imageUrl,
          },
        };
        fetch(`/api/cms-data/siteImages`, {
          method: 'PUT',
          headers: {
            'Content-Type': 'application/json',
            Authorization: `Bearer ${token}`,
          },
          body: JSON.stringify(updatedSiteImages),
        }).catch(() => {});
      }

      await saveSection(
        'homeSettings',
        settings,
        `تنظیمات ${sectionTitle} با موفقیت در سرور ذخیره و اعمال شد.`
      );
    } catch (err: any) {
      addToast('error', err.message || 'خطا در ذخیره‌سازی تنظیمات');
    } finally {
      setIsSavingHomeSettings(false);
    }
  };

