  const handleUploadGalleryImage = async (
    target: 'heroFeaturedCard' | 'featuredBefore' | 'featuredAfter' | 'testimonial' | 'caseBefore' | 'caseAfter' | 'caseExtraImage',
    e: React.ChangeEvent<HTMLInputElement>,
    index?: number
  ) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const formData = new FormData();
    formData.append('file', file);
    formData.append('category', 'gallery');
    formData.append('alt', file.name);
    formData.append('title', `تصویر ${target}`);

    setIsUploadingGalleryImage(true);
    try {
      const res = await fetch('/api/media', {
        method: 'POST',
        headers: { Authorization: `Bearer ${token}` },
        body: formData,
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || 'خطا در بارگذاری تصویر');

      const uploadedUrl = data.media?.url || data.url;

      if (target === 'heroFeaturedCard') {
        updateGallerySection('hero', (prevSec) => ({ ...prevSec, featuredCardImage: uploadedUrl }));
      } else if (target === 'featuredBefore') {
        updateGallerySection('featuredCase', (prevSec) => ({ ...prevSec, beforeImage: uploadedUrl }));
      } else if (target === 'featuredAfter') {
        updateGallerySection('featuredCase', (prevSec) => ({ ...prevSec, afterImage: uploadedUrl }));
      } else if (target === 'testimonial' && typeof index === 'number') {
        updateGallerySection('testimonials', (prevSec) => {
          const nextItems = [...(prevSec.items || [])];
          if (nextItems[index]) {
            nextItems[index] = { ...nextItems[index], image: uploadedUrl };
          }
          return { ...prevSec, items: nextItems };
        });
      } else if (target === 'caseBefore' && editingGallery) {
        setEditingGallery((prev: any) => ({
          ...prev,
          beforeImage: uploadedUrl,
          image: uploadedUrl,
        }));
      } else if (target === 'caseAfter' && editingGallery) {
        setEditingGallery((prev: any) => ({
          ...prev,
          afterImage: uploadedUrl,
          mobileImage: uploadedUrl,
        }));
      } else if (target === 'caseExtraImage' && editingGallery) {
        const curImages = editingGallery.galleryImages || [];
        setEditingGallery((prev: any) => ({
          ...prev,
          galleryImages: [
            ...curImages,
            {
              url: uploadedUrl,
              label: newCaseImageLabel.trim() || file.name,
              stage: newCaseImageStage,
            },
          ],
        }));
        setNewCaseImageLabel('');
      }

      addToast('success', 'تصویر با موفقیت بارگذاری شد. لطفاً تغییرات را ذخیره نمایید.');
      notifyCmsUpdated();
    } catch (err: any) {
      addToast('error', err.message || 'خطا در بارگذاری تصویر');
    } finally {
      setIsUploadingGalleryImage(false);
      e.target.value = '';
    }
  };

  const handleMoveCase = async (index: number, direction: 'up' | 'down') => {
    const list = [...(cmsData.transformations || [])];
    const targetIndex = direction === 'up' ? index - 1 : index + 1;
    if (targetIndex < 0 || targetIndex >= list.length) return;
    const temp = list[index];
    list[index] = list[targetIndex];
    list[targetIndex] = temp;

    try {
      const res = await fetch('/api/cms-data/transformations', {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify(list),
      });
      if (res.ok) {
        await fetchCmsData();
        notifyCmsUpdated();
        addToast('success', 'ترتیب پرونده‌ها به‌روزرسانی شد.');
      }
    } catch {
      addToast('error', 'خطا در ذخیره ترتیب پرونده‌ها.');
    }
  };

  const handleReplaceMedia = async (targetItem: any, file: File) => {
    if (!file) return;
    const formData = new FormData();
    formData.append('file', file);
    formData.append(
      'targetType',
      targetItem.category === 'site' ? 'siteImage' : targetItem.category || 'media'
    );
    if (targetItem.targetKey) formData.append('targetKey', targetItem.targetKey);
    if (targetItem.targetId) formData.append('targetId', targetItem.targetId);
    if (targetItem.targetField) formData.append('targetField', targetItem.targetField);
    formData.append('alt', editingAltIds[targetItem.id] ?? targetItem.alt ?? file.name);
    formData.append('title', targetItem.title || file.name);

    setReplacingId(targetItem.id);
    try {
      const res = await fetch('/api/media/replace', {
        method: 'POST',
        headers: { Authorization: `Bearer ${token}` },
        body: formData,
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || 'خطا در تعویض تصویر');
      addToast('success', `تصویر «${targetItem.title || targetItem.originalName || 'مورد نظر'}» با موفقیت تعویض و در سایت اعمال شد.`);
      notifyCmsUpdated();
      await fetchCmsData();
    } catch (err: any) {
      addToast('error', err.message);
    } finally {
      setReplacingId(null);
    }
  };

